1	import { FastResponse } from "srvx";
2	import { HTTPError } from "./error.ts";
3	import { isJSONSerializable } from "./utils/internal/object.ts";
4	import { sanitizeStatusCode, sanitizeStatusMessage } from "./utils/sanitize.ts";
5	import { kEventDispose, type DisposeState } from "./utils/internal/dispose.ts";
6	
7	import type { H3Config } from "./types/h3.ts";
8	import { kEventRes, kEventResHeaders, kEventResErrHeaders, type H3Event } from "./event.ts";
9	
10	export const kNotFound: symbol = /* @__PURE__ */ Symbol.for("h3.notFound");
11	export const kHandled: symbol = /* @__PURE__ */ Symbol.for("h3.handled");
12	
13	export function toResponse(
14	  val: unknown,
15	  event: H3Event,
16	  config: H3Config = {},
17	): Response | Promise<Response> {
18	  if (typeof (val as PromiseLike<unknown>)?.then === "function") {
19	    return (val as Promise<unknown>).then(
20	      (resolvedVal) => toResponse(resolvedVal, event, config),
21	      (r) => toResponse(toError(r), event, config),
22	    ) as Promise<Response>;
23	  }
24	
25	  let response: Response | Promise<Response>;
26	  try {
27	    response = prepareResponse(val, event, config);
28	  } catch (error) {
29	    return toResponse(toError(error), event, config);
30	  }
31	  if (typeof (response as PromiseLike<Response>)?.then === "function") {
32	    return toResponse(response, event, config);
33	  }
34	
35	  const { onResponse } = config;
36	  if (onResponse) {
37	    // onResponse is a terminal side-effect hook (returns void). A throw/rejection here must not
38	    // escape the lifecycle (onError already ran); absorb and log it (consistent with dispose
39	    // callbacks), then still return the already-built response. The hook is invoked inside `.then`
40	    // so a synchronous throw is caught too (not just a rejected promise).
41	    return Promise.resolve()
42	      .then(() => onResponse(response as Response, event))
43	      .catch((error) => {
44	        if (!config.silent) console.error(error);
45	      })
46	      .then(
47	        () =>
48	          ((event as any)[kEventDispose] as DisposeState | undefined)?.observe(
49	            response as Response,
50	            val,
51	          ) ?? (response as Response),
52	      );
53	  }
54	  return (
55	    ((event as any)[kEventDispose] as DisposeState | undefined)?.observe(
56	      response as Response,
57	      val,
58	    ) ?? (response as Response)
59	  );
60	}
61	
62	/**
63	 * Normalize a thrown or rejected value before rendering it as a response.
64	 *
65	 * Errors and the internal sentinels are passed through, and numbers are coerced to a status code
66	 * (`throw 404`). Anything else — an object, a string, `undefined` — is wrapped into an unhandled
67	 * 500, so it is logged instead of being rendered as a successful response body.
68	 *
69	 * Nothing is taken from the thrown value: `status`, `message`, `data`, `statusText` and `headers`
70	 * are all dropped, and the value is kept as `cause`, which is never serialized. A non-Error object
71	 * is never trusted to shape the response, not even via a `status` shorthand.
72	 */
73	export function toError(value: unknown): unknown {
74	  if (value === kNotFound || value === kHandled || value instanceof Error) {
75	    return value;
76	  }
77	  if (typeof value === "number") {
78	    return new HTTPError({ status: value });
79	  }
80	  const error = new HTTPError({ status: 500, unhandled: true });
81	  (error as { cause: unknown }).cause = value;
82	  return error;
83	}
84	
85	/**
86	 * Brand for {@link HTTPResponse}, checked instead of `constructor.name`.
87	 *
88	 * A duck-typed name check is forgeable from untrusted input: `JSON.parse` creates an *own*
89	 * `constructor` property, so a request body like `{"constructor":{"name":"HTTPResponse"}}` echoed
90	 * back by a handler would be accepted as a response descriptor and get to pick the response body,
91	 * headers and status. A registry symbol cannot appear in JSON while still matching across
92	 * duplicate module instances (multiple h3 copies, realms).
93	 */
94	const kHTTPResponse: unique symbol = /* @__PURE__ */ Symbol.for("h3.HTTPResponse");
95	
96	export class HTTPResponse {
97	  #headers?: Headers;
98	  #init?: Pick<ResponseInit, "status" | "statusText" | "headers"> | undefined;
99	  body?: BodyInit | null;
100	  constructor(
101	    body: BodyInit | null,
102	    init?: Pick<ResponseInit, "status" | "statusText" | "headers">,
103	  ) {
104	    this.body = body;
105	    this.#init = init;
106	  }
107	  /**
